-- 타입이 어느 jar 에서 왔나

@Test
void 타입의_주인() {
    Class<?>[] types = {
        JpaRepository.class, PagingAndSortingRepository.class,
        Page.class, Pageable.class, Sort.class,
        EntityManager.class, Entity.class,
        Session.class, SessionFactory.class
    };
    for (Class<?> c : types) {
        String jar = c.getProtectionDomain().getCodeSource()
                      .getLocation().getPath();
        System.out.printf("%-28s %s%n", c.getSimpleName(),
                jar.substring(jar.lastIndexOf('/') + 1));
    }
}

